package org.novasos.healthysv2.laboratory;
import static org.assertj.core.api.Assertions.*;import java.util.*;import org.junit.jupiter.api.Test;import org.novasos.healthysv2.TestcontainersConfiguration;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.context.annotation.Import;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;
@ActiveProfiles("test")@SpringBootTest@Import(TestcontainersConfiguration.class)@Transactional class LaboratoryRepositoryIntegrationTests{
 @Autowired LabOrderRepository repository;@Autowired JdbcTemplate jdbc;
 @Test void persistsCompleteLaboratoryAggregate(){Graph g=graph();var order=LabOrder.create(g.patient,null,g.professional,g.organization,"STAT");var ordered=order.addItem(g.exam,"Urgent");var specimen=order.collect(ordered.getId(),"SP-"+UUID.randomUUID(),"BLOOD",null,g.professional);order.receive(specimen.getId());var result=order.createResult(g.professional,null,"CBC");result.addItem(ordered,g.parameter,null,"12.5","g/dL",null,null,"Within range","NORMAL");order.validateResult(result.getId(),g.professional);var saved=repository.saveAndFlush(order);var found=repository.findById(saved.getId()).orElseThrow();assertThat(found.getItems()).singleElement().satisfies(i->assertThat(i.getSpecimens()).hasSize(1));assertThat(found.getResults()).singleElement().satisfies(r->assertThat(r.getItems()).hasSize(1));assertThat(jdbc.queryForObject("select status from laboratory.lab_order where id=?",String.class,saved.getId())).isEqualTo("COMPLETED");}
 private Graph graph(){UUID patientPerson=person(),professionalPerson=person(),patient=UUID.randomUUID(),professional=UUID.randomUUID(),organization=UUID.randomUUID(),exam=UUID.randomUUID(),parameter=UUID.randomUUID();jdbc.update("insert into patient.patient(id,person_id,patient_number) values (?,?,?)",patient,patientPerson,"PAT-"+patient);jdbc.update("insert into professional.professional(id,person_id,professional_number,professional_type,status) values (?,?,?,?,?)",professional,professionalPerson,"PRO-"+professional,"LAB_TECHNICIAN","ACTIVE");jdbc.update("insert into organization.organization(id,organization_number,name) values (?,?,?)",organization,"ORG-"+organization,"Laboratory");jdbc.update("insert into catalog.laboratory_exam_catalog(id,code,name,specimen_type,active) values (?,?,?,?,?)",exam,"CBC-"+exam.toString().substring(0,4),"Complete blood count","BLOOD",true);jdbc.update("insert into catalog.laboratory_parameter_catalog(id,exam_id,code,name,unit) values (?,?,?,?,?)",parameter,exam,"HGB","Hemoglobin","g/dL");return new Graph(patient,professional,organization,exam,parameter);}private UUID person(){UUID id=UUID.randomUUID();jdbc.update("insert into identity.person(id,person_number,first_name,last_name,status) values (?,?,?,?,?)",id,"PER-"+id,"Test","User","ACTIVE");return id;}record Graph(UUID patient,UUID professional,UUID organization,UUID exam,UUID parameter){}
}
